package io.github.openflocon.flocon.myapplication.multi.database

import io.github.openflocon.flocon.myapplication.multi.sqldelight.SqlDelightDatabase
import kotlin.random.Random

/** A random dog, inserted with the queries generated by SQLDelight. */
fun SqlDelightDatabase.insertSampleDog() {
    dogQueries.insertDog(
        name = "Flocon",
        breed = listOf("Golden Retriever", "Basset", "Yorkshire").random(),
        age = Random.nextLong(1, 15),
    )
}
